<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Khóa học | HànNgữ</title><link rel="stylesheet" href="style.css"><style>.page{max-width:960px;margin:auto;padding:110px 24px 60px}.box{background:#fff;border-radius:18px;padding:26px;box-shadow:0 6px 25px #0f172a12;margin:18px 0}.price{font-size:1.55rem;font-weight:800;color:#0d9488}.qr{max-width:290px;width:100%;border-radius:12px}.hidden{display:none}.muted{color:#64748b}.lesson{padding:12px 0;border-bottom:1px solid #e2e8f0}</style></head><body><?php include 'sidebar.php'; ?><main class="page"><div id="app" class="box">Đang tải khóa học...</div></main><script>
const slug=new URLSearchParams(location.search).get('slug'), app=document.getElementById('app'); let course,token;
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' đ'; async function csrf(){if(!token)token=(await fetch('api.php?action=get_csrf_token')).json().then(x=>x.csrf_token);return token}
async function order(){let t=await csrf(),r=await fetch('api.php?action=create_order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({course_id:course.id,csrf_token:t})}).then(x=>x.json());if(!r.success){alert(r.message);if(r.message.includes('đăng nhập'))location='login.php';return}showPay(r.order)}
function showPay(o){document.getElementById('pay').innerHTML=`<h2>Quét QR để thanh toán</h2><p>Chuyển chính xác <b>${money(o.amount)}</b>. Nội dung bắt buộc: <b>${o.order_code}</b></p>${o.qr_url?`<img class="qr" src="${o.qr_url}" alt="QR thanh toán">`:'<p class="muted">Admin chưa cấu hình tài khoản nhận tiền. Vui lòng liên hệ quản trị viên.</p>'}<p id="payment-status" class="muted">Đang chờ xác nhận thanh toán...</p><p class="muted">Đơn tự hết hạn sau 30 phút. Ngay khi ngân hàng báo có hoặc admin xác nhận, khóa học sẽ được cấp và hóa đơn được gửi email.</p>`;document.getElementById('pay').scrollIntoView({behavior:'smooth'});pollOrder(o.id)}
function pollOrder(id){let timer=setInterval(async()=>{let r=await fetch('api.php?action=get_order&id='+id).then(x=>x.json()).catch(()=>null);if(!r||!r.success)return;let status=document.getElementById('payment-status');if(r.order.status==='paid'){clearInterval(timer);if(status)status.innerHTML='<b style="color:#047857">Thanh toán thành công! Đang mở khóa học...</b>';setTimeout(()=>location.reload(),1200)}else if(r.order.status!=='pending'){clearInterval(timer);if(status)status.textContent='Đơn hàng đã '+r.order.status+'.'}},5000)}
fetch('api.php?action=get_course&slug='+encodeURIComponent(slug)).then(x=>x.json()).then(r=>{if(!r.success){app.textContent=r.message;return}course=r.course;app.innerHTML=`<span class="muted">${course.hsk_level?'HSK '+course.hsk_level:'Khóa học'}</span><h1>${course.title}</h1><p>${course.description||course.short_description||''}</p><p class="price">${money(course.price)}</p>${course.enrolled?'<a class="btn btn--primary" href="lessons.php">Vào học ngay</a>':'<button id="buy" class="btn btn--primary">Mua khóa học</button>'}<h2>Nội dung khóa học</h2>${course.lessons.length?course.lessons.map((l,i)=>`<div class="lesson">${i+1}. ${l.title}</div>`).join(''):'<p class="muted">Admin đang cập nhật nội dung bài học.</p>'}<div id="pay" class="box hidden"></div>`;if(!course.enrolled)document.getElementById('buy').onclick=()=>{document.getElementById('pay').classList.remove('hidden');order()}});
</script></body></html>
